/// Sequence `SequenceFileLoad`.
Future<String> sequenceFileLoad() async {
  final run = ts.SequenceRun();
  final dynamic explanationResult = ts.PropObj({
    'Error': ts.PropObj({'Code': 0, 'Msg': '', 'Occurred': false}),
    'Status': '',
    'ButtonHit': 0,
    'Response': '',
    'ReportText': '',
    'Common': ts.PropObj(),
  }); // result of Explanation
  final dynamic launchReadmeResult = ts.PropObj({
    'Error': ts.PropObj({'Code': 0, 'Msg': '', 'Occurred': false}),
    'Status': '',
    'ExitCode': 0,
    'ReportText': '',
    'Common': ts.PropObj(),
  }); // result of Launch Readme

  // popup title: "About This Example"
  // popup message: "This example demonstrates testing an imagined part on up to 4 sites.  |   | Prerequisites | You must have the following software installed if you want to use the example: | - STS Software 25.0.0 or later |   | Review the README file accompanying the sequence file  | for information about how to use this example."
  // popup buttons: "Help" | "OK"
  // Explanation [MessagePopup]: acts through ts.stepHost
  final popup = await ts.stepHost.messagePopup(
    title: 'About This Example',
    message:
        'This example demonstrates testing an imagined part on up to 4 sites. \n \nPrerequisites\nYou must have the following software installed if you want to use the example:\n- STS Software 25.0.0 or later\n \nReview the README file accompanying the sequence file \nfor information about how to use this example.',
    buttons: ['Help', 'OK', '', '', '', ''],
  );
  explanationResult.ButtonHit = popup.buttonHit;
  explanationResult.Response = popup.response;
  explanationResult.Status = 'Done';
  run.record(explanationResult.Status);
  // Launch README.md in notepad on clicking help.
  // runs executable: notepad.exe "README.md" (WAIT_NONE)
  if (ts.cond('RunState.PreviousStep.Result.ButtonHit == 1')) {
    // precondition of Launch Readme
    // Launch Readme [CallExecutable]: acts through ts.stepHost
    await ts.stepHost.runStepType(
      'CallExecutable',
      ts.StepPhase.post,
      ts.PropObj({
        'Executable': 'notepad.exe',
        'ExecutableExpr': '',
        'SpecifyExeByExpr': false,
        'ExecutableCalled': '',
        'Arguments': '"README.md"',
        'WaitCondition': 'WAIT_NONE',
        'TimeToWait': 0,
        'SetErrorCode': false,
        'InitialWindowState': 'WINSTATE_SHOWNORM_A',
        'TerminateOnAbort': false,
        'StoreProcessHandle': false,
        'ProcessHandleExpr': 'Step.ProcessHandlePtr',
        'ProcessHandle': 0,
        'ProcessHandlePtr': null,
        'ExitCodeStatusAction': 'EXIT_CODE_NO_ACTION',
        'ExitCodeErrorAction': 'EXIT_CODE_NO_ACTION',
        'WorkingDir': ts.PropObj({'Source': 2, 'Expr': '', 'IsExpr': false}),
        'RemoteSettings': ts.PropObj({
          'Enabled': false,
          'Host': '""',
          'HostByExpr': true,
          'Port': '13540',
          'Password': '',
          'PasswordByExpr': false,
        }),
        'StdInput': ts.PropObj({'Type': 0, 'Source': '""', 'IsExpr': false}),
        'StdOutput': ts.PropObj({'Dest': 0, 'Expr': 'Step.StdOutput.Text', 'IsExpr': false, 'Text': ''}),
        'StdError': ts.PropObj({
          'Dest': 0,
          'Expr': 'Step.StdError.Text',
          'IsExpr': false,
          'Text': '',
          'Action': 0,
          'SetErrorMsg': false,
        }),
      }),
      launchReadmeResult,
    );
    launchReadmeResult.Status = 'Done';
    run.record(launchReadmeResult.Status);
  } else {
    launchReadmeResult.Status = 'Skipped';
  }

  return run.status;
}
